 function fallbackKeyExpressions(english){const stop=new Set(['this','that','with','from','have','will','your','they','them','then','when','what','where','there','here','into','about','some','just','very','really']);const words=String(english||'').toLowerCase().match(/[a-z][a-z'-]*/g)||[];return [...new Set(words.filter(word=>word.length>=4&&!stop.has(word)))].sort((a,b)=>b.length-a.length).slice(0,2)}
 function fallbackGrammar(english){const text=String(english||'');if(/\b(am|is|are)\s+going to\b/i.test(text))return 'be going to + 动词原形表示计划或即将发生的动作；结合时间状语理解发生时间。';if(/\b(am|is|are)\s+[a-z]+ing\b/i.test(text))return 'be + 动词-ing 构成现在进行时，表示说话时正在发生或已经安排的动作。';if(/\b(have|has) got\b/i.test(text))return 'have/has got + 名词表示“拥有”，在人称变化时同步调整助动词。';if(/\b(will|'ll)\s+[a-z]+\b/i.test(text))return 'will / ’ll + 动词原形构成一般将来时，表示预测、决定或将来的动作。';if(/\blet's\s+[a-z]+\b/i.test(text))return "let's + 动词原形用于提出共同建议，后接动作内容。";if(/^\s*(come|go|take|make|look|listen|try|keep)\b/i.test(text))return '动词原形置于句首构成祈使句，主语 you 通常省略。';if(/\b(this|that|it)\s+(is|was)\b/i.test(text))return '指示代词/人称代词 + be 动词构成主系表结构，后接身份、状态或事物名称。';return '本句按“主语 + 谓语 + 补充信息”展开；先识别核心谓语，再结合时间、地点或方式成分理解。'}
 function analyzeSentenceLearningFields(sentence){const english=String(sentence.english||'').trim(),rule=LEARNING_ANALYSIS_RULES.find(item=>item.test.test(english));const keyWords=(rule?.keyWords?.length?rule.keyWords:(sentence.keyWords||[]).length?sentence.keyWords:fallbackKeyExpressions(english)).slice(0,3);return {keyWords,grammar:rule?.grammar||sentence.grammar||fallbackGrammar(english),learningAnalysis:{method:'控制端句子级预分析',confidence:rule?96:82,requiresReview:true,analyzedAt:new Date().toISOString()}}}
