function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.spark}</svg>`}
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon)})}
function asset(src){const value=String(src||'');if(!value)return '../assets/images/home_video_1.png';if(/^https:\/\//i.test(value)||/^\/(?!\/)/.test(value)||/^blob:/i.test(value)||/^data:image\/(?:png|jpe?g|gif|webp);base64,/i.test(value))return value;if(value.startsWith('../'))return value;return '../'+value.replace(/^\.\//,'')}
function toast(msg){const el=$('#toast'),failed=/失败|未完成|中断|异常|错误|拒绝|缺少|无效/.test(String(msg));el.textContent=msg;el.classList.toggle('error',failed);el.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>el.classList.remove('show','error'),failed?6000:2600)}
function fmtDuration(s){s=Math.max(0,Math.round(Number(s)||0));return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`}
function videoTitle(id){const v=Store.getVideo(id);return v?.titleZh||localizeTitle(v?.title)||`视频 #${id}`}
