function replaceViewContent(root,html){
 // Reuse a loaded cover only within the same authenticated view. Build off-DOM
 // so a polling redraw cannot start another image request before reuse.
 const retained=new Map();
 for(const img of root.querySelectorAll('img[data-cover-preview]')){
  if(AdminAuth.context&&img.__eastudyCoverContext===AdminAuth.context&&img.complete&&img.naturalWidth>0&&
    img.getAttribute('src')===img.dataset.coverPreview){
   const key=img.dataset.coverPreview;
   if(!retained.has(key))retained.set(key,[]);
   retained.get(key).push(img);
  }
 }
 const template=document.createElement('template');template.innerHTML=html;const replacements=[];
 for(const img of template.content.querySelectorAll('img[data-cover-preview]')){
  const previous=retained.get(img.dataset.coverPreview)?.shift();
  if(previous){
   previous.dataset.coverFallback=img.dataset.coverFallback;
   const slot=document.createElement('span');img.replaceWith(slot);replacements.push([slot,previous]);
  }
 }
 root.replaceChildren(template.content);
 // Never adopt a loaded image into the template's inert document: that resets it.
 for(const [slot,img] of replacements)slot.replaceWith(img);
}
