function pipelineSteps(job){if(!Store.localOnly&&window.EastudyProcessingControl)return window.EastudyProcessingControl.renderSteps(job);const names={download:'下载云端原片',upload:'保存上传文件',probe:'检查视频与音轨',transcode:'生成540P视频',asr:'英文字幕与词级时间轴',enrich:job.type==='LEARNING_REPAIR'?'完善学习内容':'翻译、难度、分类与简介',output:'回传云端成品',review:'人工审核'};return `<div class="pipeline-steps">${(job.steps||[]).map(([n,s],i)=>`<div class="pipeline-step ${stepStatusClass(s)}"><span class="step-icon">${s==='SUCCESS'?'✓':String(i+1).padStart(2,'0')}</span><span><b>${names[n]||n}</b><small>${n}</small></span>${status(s)}</div>`).join('')}</div>`}
function secondsText(value){if(value===null||value===undefined||value==='')return '暂无法估算';const seconds=Number(value);if(!Number.isFinite(seconds)||seconds<0)return '暂无法估算';if(seconds<60)return `约 ${Math.ceil(seconds)} 秒`;const minutes=Math.ceil(seconds/60);return minutes<60?`约 ${minutes} 分钟`:`约 ${Math.floor(minutes/60)} 小时 ${minutes%60} 分钟`}
function ageText(value,now=Date.now()){return window.EastudyRelativeTime?.relativeTimeZh(value,now)||'尚未上报'}
function amountText(j){const current=Number(j.current),total=Number(j.total);if(!Number.isFinite(current)||!Number.isFinite(total)||total<=0)return '正在采集实际完成量';if(j.unit==='bytes')return `${(current/1048576).toFixed(1)} / ${(total/1048576).toFixed(1)} MB`;if(j.unit==='media_seconds')return `${fmtDuration(current)} / ${fmtDuration(total)}`;return `${Math.round(current)} / ${Math.round(total)} ${j.unit==='files'?'个文件':j.unit==='batches'?'批':'项'}`}
function stageText(j){const resume=j.type==='CLOUD_PIPELINE'&&j.resumePosition;if(resume&&!['REVIEW','CANCELLED'].includes(j.rawStatus||j.status)){if(resume.verified&&resume.phase==='final')return '成品已校验，继续回传';return `${resume.phase==='stages'?'复用阶段断点':'校验断点'}（上次进度 ${Math.min(99,Math.max(0,Number(resume.progress)||0))}%）`}const names={LOCAL_DOWNLOAD:'下载云端原片',PROBE:'检查视频与音轨',TRANSCODE:'生成540P视频',ASR:'识别英文字幕',ENRICH:j.type==='LEARNING_REPAIR'?'完善学习内容':'翻译与学习分析',LOCAL_UPLOAD:'回传云端成品',REVIEW:'等待人工审核'};return names[j.stage]||j.currentStep||'等待处理'}
function jobVideoState(j){if(j.videoState)return j.videoState;return Store.getVideo(j.videoId)?'ACTIVE':'MISSING'}
function jobTitle(j){return Store.getVideo(j.videoId)?.title||j.title||j.inputTitle||`视频 #${j.videoId}`}
function jobStateText(j){const state=jobVideoState(j);return state==='TRASHED'?'视频已移入回收站':state==='MISSING'?'视频记录缺失，需要核对恢复':'视频记录正常'}
function deriveActivity(j){const raw=String(j.rawStatus||j.status||'WAITING').toUpperCase(),state=jobVideoState(j);if(state==='TRASHED')return {code:'VIDEO_TRASHED',text:'视频已移入回收站，任务历史已保留'};if(state==='MISSING')return {code:'VIDEO_MISSING',text:'视频记录缺失，需要核对关联'};if(raw==='CANCELLED')return {code:'CANCELLED',text:'任务已取消'};if(raw==='REVIEW')return {code:'REVIEW',text:j.type==='MEDIA_REENCODE'?'视频优化已完成，学习内容保持不变':'自动处理完成，等待人工审核'};if(raw==='ERROR')return {code:'ERROR',text:'处理失败'};if(CloudState.jobsSyncError)return {code:'SYNC_UNKNOWN',text:'页面同步中断，当前状态暂无法确认'};const workerReady=Store.localOnly?true:Boolean(CloudState.service?.ready);if(['QUEUED','WAITING'].includes(raw)&&!workerReady)return {code:'NODE_OFFLINE',text:'已安全排队，等待处理节点上线'};const heartbeat=Date.parse(j.lastHeartbeatAt||'');const progress=Date.parse(j.lastProgressAt||'');if(raw==='RUNNING'&&(!Number.isFinite(heartbeat)||Date.now()-heartbeat>90000))return {code:'CONTACT_LOST',text:'任务租约仍在记录中，但暂时联系不上处理节点'};if(raw==='RUNNING'&&Number.isFinite(progress)&&Date.now()-progress>180000)return {code:'NO_RECENT_PROGRESS',text:'处理节点在线，当前步骤暂未产生新结果'};const resume=j.type==='CLOUD_PIPELINE'&&j.resumePosition;if(resume){if(['QUEUED','WAITING'].includes(raw)||!resume.verified&&resume.phase!=='stages')return {code:'RESUME_VALIDATING',text:'等待或正在校验断点，保留上次进度'};if(resume.verified&&resume.phase==='final')return {code:'RESUME_FINAL',text:'成品校验通过，继续回传，无需重新调用 AI'};return {code:'RESUME_STAGES',text:'正在复用有效阶段断点并处理剩余内容'}}if(raw==='QUEUED')return {code:'QUEUED',text:'已入队，等待处理节点领取'};if(raw==='WAITING')return {code:'WAITING',text:'等待重试时间或可用处理节点'};return {code:'RUNNING',text:'处理节点正在执行当前步骤'}}
function activityText(j){return deriveActivity(j).text}
function jobCoverImage(j,v){
 const fallback=asset(v.cover||j.cover),preview=String(j.previewCover||'');
 const match=preview.match(/^\/api\/processing\/media\/([0-9a-f-]{36})\/cover(?:-(?:320|640|960))?\.webp\?previewRun=([0-9a-f-]{36})$/);
 if(!match||match[1]!==j.id||match[2]!==j.runId)return `<img src="${escapeHtml(fallback)}" alt="">`;
 return `<img src="${escapeHtml(preview)}" data-cover-preview="${escapeHtml(preview)}" data-cover-fallback="${escapeHtml(fallback)}" alt="">`;
}
function videoCoverImage(video){
 const job=allJobs().find(row=>String(row.id)===String(video.processingJobId)&&String(row.videoId)===String(video.id));
 return job?jobCoverImage(job,video):`<img src="${escapeHtml(asset(video.cover))}" alt="">`;
}
function bindCoverPreviews(){
 $$('img[data-cover-preview]').forEach(img=>{
  if(img.dataset.coverBound)return;
  img.dataset.coverBound='true';img.__eastudyCoverContext=AdminAuth.context;
  const context=AdminAuth.context,userId=context?.user?.id,preview=img.dataset.coverPreview;
  let retried=false,pending=false;
  const active=()=>img.isConnected&&!!context&&AdminAuth.context===context&&context.user?.id===userId;
  const fallback=()=>{img.onerror=null;img.src=img.dataset.coverFallback};
  img.onerror=async()=>{
   if(pending)return;
   if(!active()){img.onerror=null;return}
   if(retried||!Cloud?.syncMediaSession){fallback();return}
   retried=true;pending=true;
   try{
    // Covers use the catalog cookie, never a job-scoped playback session.
    const result=await Cloud.syncMediaSession('admin',{force:true});
    if(!active()){img.onerror=null;return}
    if(result?.stale){fallback();return}
    img.src=preview;
   }catch{if(active())fallback();else img.onerror=null}
   finally{pending=false}
  };
  if(img.complete&&!img.naturalWidth)void img.onerror();
 });
}
