function renderPipeline(){const groups=pipelineVideoGroups(),current=groups.filter(g=>(g.current.rawStatus||g.current.status)!=='CANCELLED'),history=groups.filter(g=>(g.current.rawStatus||g.current.status)==='CANCELLED'),sync=Store.localOnly?'本地数据':CloudState.jobsSyncError?'页面同步中断，正在自动重连':CloudState.lastJobsSyncAt?`页面数据 ${ageText(new Date(CloudState.lastJobsSyncAt).toISOString())}同步`:'正在同步云端任务',total=Store.localOnly?groups.length:ProcessingView.total,totalPages=Math.max(1,Math.ceil(total/ProcessingView.pageSize)),pager=Store.localOnly?'':`<div class="learner-pagination"><button class="secondary" id="processingPrev" ${ProcessingView.page<=1?'disabled':''}>上一页</button><span>第 ${ProcessingView.page} / ${totalPages} 页 · 共 ${total} 个视频</span><button class="secondary" id="processingNext" ${ProcessingView.page>=totalPages?'disabled':''}>下一页</button></div>`;view(`${pageHead('AI STUDIO','解析队列',(Store.localOnly?'本机处理：请保持处理程序运行。':`原片与成品保存在云端，当前电脑只提供转码和语音识别算力。${sync}`),`<button class="secondary" data-refresh-studio-jobs>刷新状态</button><button class="ghost" data-action="run-audit">${icon('check')}内容检查</button>`)}<p role="status">${escapeHtml(window.EastudyStudioV2?.recoveryMessage('refresh')||'')}</p>${processingMetrics()}<section class="pipeline-group"><h2>本页视频（${groups.length}）</h2><div class="job-grid">${current.map(videoWorkCard).join('')||'<div class="empty">暂无当前解析任务</div>'}</div></section>${history.length?`<section class="pipeline-group pipeline-history"><h2>本页已结束视频</h2><p>每个视频集中显示，技术任务按需分页读取。</p><div class="job-grid">${history.map(videoWorkCard).join('')}</div></section>`:''}${pager}`,'AI Processing');$('#processingPrev')?.addEventListener('click',()=>void changeProcessingPage(ProcessingView.page-1));$('#processingNext')?.addEventListener('click',()=>void changeProcessingPage(ProcessingView.page+1))}
