function renderTrash(){
 const rows=Store.localOnly?Store.listTrash():CloudState.trash;
 const deletionReady=CloudState.deletionCapability?.ready===true;
 view(`${pageHead(Store.localOnly?'LOCAL TRASH':'CLOUD TRASH','回收站','移入回收站后仍可恢复；永久删除会在后台清理该视频独占的云端文件和解析记录，完成后无法恢复。','<button class="ghost" data-goto="#/videos">返回视频库</button><button class="secondary" data-export-content>导出内容备份</button>')}
 ${!Store.localOnly&&!deletionReady?`<p role="status">${escapeHtml(deletionErrorMessage(CloudState.deletionCapability?.reasons?.[0]||'DELETION_HEALTH_UNAVAILABLE'))}<button class="ghost" data-refresh-deletion>重新检查</button></p>`:''}
 <div class="table-wrap"><table class="data-table"><thead><tr><th>视频</th><th>删除时间</th><th>状态</th><th>操作</th></tr></thead><tbody>${rows.map(row=>{const deletion=row.deletion||null,irreversible=Boolean(deletion?.confirmedAt),busy=deletion&&['QUEUED','DELETING','RETRY'].includes(deletion.state),attention=deletion?.state==='NEEDS_ATTENTION',state=busy?`清理中 · 已删除 ${Number(deletion.deletedObjects)||0} 个文件`:attention?'清理中断，可继续清理':'可恢复';return `<tr><td>${escapeHtml(row.video?.titleZh||row.video?.title||'已删除视频')}<small> #${Number(row.video?.id||row.videoId)}</small></td><td>${escapeHtml(new Date(row.deletedAt).toLocaleString())}</td><td><span class="invite-state ${attention?'revoked':busy?'reserved':'available'}">${state}</span></td><td><button class="ghost" data-restore-video="${Number(row.video?.id||row.videoId)}" ${irreversible||busy?'disabled':''}>${irreversible?'永久删除已开始':'恢复为草稿'}</button>${Store.localOnly?'':`<button class="danger compact" data-permanent-delete-video="${Number(row.video?.id||row.videoId)}" ${busy||!deletionReady?'disabled':''}>${attention&&irreversible?'继续清理':'永久删除'}</button>`}</td></tr>`}).join('')||'<tr><td colspan="4"><div class="empty">回收站为空</div></td></tr>'}</tbody></table></div>`,'回收站');
 for(const row of rows)if(row.deletion&&['QUEUED','DELETING','RETRY'].includes(row.deletion.state))void pollPermanentDeletion(row.deletion.deletionId);
}
function deletionErrorMessage(code){return ({VIDEO_DELETION_DISABLED:'永久删除服务尚未启用，请在部署配置中启用清理服务。',R2_VIDEO_BUCKET_NOT_BOUND:'云端文件存储尚未连接，暂时无法清理。',DELETION_SERVICE_NOT_CONFIGURED:'云端清理服务的数据库连接尚未配置。',DELETION_WORKER_NOT_CONFIGURED:'云端清理服务的任务凭据尚未配置。',DELETION_SCHEDULER_NOT_CONFIGURED:'后台定时清理尚未配置，暂时无法开始永久删除。',DELETION_HEALTH_UNAVAILABLE:'暂时无法确认清理服务状态，请重新检查。',DELETION_PLAN_EXPIRED_OR_USED:'删除确认已过期，请重新发起删除。',DELETION_PLAN_NOT_FOUND:'删除确认已失效，请刷新回收站后重试。',PERMANENT_DELETE_CONFIRMATION_REQUIRED:'该视频还未确认永久删除，请重新操作。',VIDEO_PERMANENT_DELETION_STARTED:'永久删除已经开始，不能再恢复为草稿。'})[code]||''}
function cloudErrorMessage(error){const message=String(error?.message||error||'未知错误');if(error?.issues?.length)return error.issues[0].message;if(message.includes('CONTENT_REVISION_CONFLICT'))return '内容已被其他操作更新，请重新检查后重试。';if(message.includes('VIDEO_PROCESSING_ACTIVE'))return '该视频已有处理任务，请在处理中心等待完成后再操作。';if(message.includes('LEARNING_SOURCE_CHANGED'))return '分析期间内容已被修改，已保留人工修改。请重新创建教学任务。';if(message.includes('LEARNING_REPAIR_SOURCE_MISSING'))return '视频来源记录不完整，请在视频详情检查处理记录。';if(message.includes('VIDEO_REMOVAL_REQUIRES_EXPLICIT_TRASH'))return '检测到旧页面试图覆盖视频目录，已被云端拦截。请刷新页面后重试。';if(message.includes('CONTENT_EXPECTED_REVISION_REQUIRED'))return '页面版本过旧，已拒绝写入。请强制刷新后重试。';if(message.includes('PUBLISHED_TAGS_MISSING'))return '请先审核并确认至少一个带字幕依据的内容标签。';if(message.includes('PUBLISH_BLOCKED'))return '发布检查未通过，请先处理列出的字幕、释义或标签问题。';if(message.includes('NO_LEARNING_REPAIR_REQUIRED'))return '当前没有需要补齐的释义。';if(message.includes('ADMIN_REQUIRED'))return '当前账号没有管理员权限。';return message}
async function approveVideoTags(videoId){const before=Store.snapshot(),video=Store.getVideo(videoId),rows=Store.listSentences(videoId);if(!video)throw new Error('VIDEO_NOT_FOUND');const allowed=LearningContract.ALLOWED_TAGS,sentenceIds=rows.map(row=>String(row.id)).filter(Boolean),direct=[...(video.tagAssignments||[]),...(video.tagIds||[]).map(tagId=>({tagId}))],seen=new Set(),assignments=[];for(const raw of direct){const tagId=String(raw?.tagId||raw?.id||'');if(!allowed.has(tagId)||seen.has(tagId))continue;seen.add(tagId);const evidence=(Array.isArray(raw.sentenceIds)?raw.sentenceIds.map(String).filter(id=>sentenceIds.includes(id)):[]);assignments.push({...raw,tagId,sentenceIds:evidence.length?evidence:sentenceIds.slice(0,3),reasonZh:String(raw.reasonZh||raw.reason||raw.evidence||'管理员依据视频标题、简介和字幕确认').trim(),reviewStatus:'APPROVED',source:raw.source||'manual'})}if(!assignments.length)throw new Error('PUBLISHED_TAGS_MISSING');const next=Store.saveVideo({...video,tagAssignments:assignments,tagIds:assignments.map(row=>row.tagId)});try{if(!Store.localOnly){cancelCloudDraftSync();const result=await Cloud.saveDraft(Store.snapshot(),CloudState.revision);if(result?.error)throw result.error;CloudState.revision=Number(result.data?.revision)||CloudState.revision}return next}catch(error){cloudImporting=true;try{Store.importSnapshot(before,{type:'cloud.import',reason:'tag-save-rollback'})}finally{cloudImporting=false}throw error}}
async function startLearningRepair(videoId,mode='fill_missing',checkedRevision=null){
 if(Store.localOnly)throw new Error('生产教学任务需要从云端控制端创建');
 await flushCloudDraftSync();
 const expectedRevision=checkedRevision===null?CloudState.revision:Number(checkedRevision);
 const result=await Cloud.createLearningRepair(videoId,expectedRevision,mode);
 if(result?.error)throw result.error;
 if(!result.data?.snapshot)throw new Error('LEARNING_REPAIR_RESPONSE_INVALID');
 importCloudMutation(result);
 try{await refreshCloudJobs()}catch(error){toast('任务已创建，处理进度暂未刷新，请到处理中心查看')}
 return result.data.job;
}
async function refreshCloudTrash(){if(Store.localOnly||!Cloud)return;const [result,capability]=await Promise.all([Cloud.listTrash(),Cloud.getVideoDeletionCapability().catch(()=>({ready:false,reasons:['DELETION_HEALTH_UNAVAILABLE']}))]);if(result.error)throw result.error;CloudState.deletionCapability=capability;CloudState.trash=result.rows.map(row=>({video:row.video,videoId:row.video_id,deletedAt:row.deleted_at,reason:row.reason,deletion:row.deletion||null}))}
async function refreshProcessingContent(){
 if(Store.localOnly||!Cloud||!AdminAuth.context)return false;
 if(processingContentRequest)return processingContentRequest;
 const context=AdminAuth.context;
 processingContentRequest=(async()=>{
  // Never overwrite pending local edits or pretend a failed save was synchronized.
  if(cloudSyncTimer)return false;
  await cloudSyncPromise;
  if(cloudSyncTimer||AdminAuth.context!==context)return false;
  const generation=contentEditGeneration;
  const remote=await Cloud.pullAdmin();
  if(remote.error)throw remote.error;
  if(!remote.snapshot)throw new Error('CLOUD_CONTENT_RESPONSE_INVALID');
  if(AdminAuth.context!==context||cloudSyncTimer||generation!==contentEditGeneration)return false;
  if(Number(remote.revision)<CloudState.revision)return false;
  cloudImporting=true;
  try{Store.importSnapshot(remote.snapshot,{type:'cloud.import',revision:remote.revision})}finally{cloudImporting=false}
  CloudState.revision=Number(remote.revision)||CloudState.revision;
  updateCounts();
  window.dispatchEvent(new CustomEvent('eastudy:processing-content-updated'));
  return true;
 })();
 try{return await processingContentRequest}finally{processingContentRequest=null}
}
async function refreshCloudJobs(){if(Store.localOnly||!Cloud)return;const result=await Cloud.listProcessingJobs(ProcessingView.page,ProcessingView.pageSize);if(result.error){CloudState.jobsSyncError=result.error;throw result.error}CloudState.summary=result.summary||null;CloudState.jobs=result.rows;CloudState.videoGroups=result.groups;CloudState.processingTotal=result.total;ProcessingView.total=result.total;CloudState.jobsSyncError=null;CloudState.lastJobsSyncAt=Date.now();updateCounts();window.dispatchEvent(new CustomEvent('eastudy:studio-job-updated'));return result.rows}
async function pollPermanentDeletion(deletionId){
 const generation=trashViewGeneration,key=generation+':'+deletionId;
 if(deletionPolls.has(key))return;
 deletionPolls.add(key);
 const active=()=>Boolean(AdminAuth.context)&&routePath()==='/trash'&&generation===trashViewGeneration;
 try{while(active()){
  await new Promise(resolve=>setTimeout(resolve,2500));if(!active())return;
  let state;try{state=await Cloud.getVideoDeletion(deletionId)}catch{continue}if(!active())return;
  const row=CloudState.trash.find(item=>String(item.videoId||item.video?.id)===String(state.videoId));
  if(row)row.deletion=state;
  if(state.state==='DONE'){await Promise.all([refreshCloudTrash(),refreshCloudJobs()]);if(!active())return;renderTrash();toast('视频及其独占云端文件已永久删除');return}
  renderTrash();if(state.state==='NEEDS_ATTENTION'){toast('云端清理遇到问题，可在回收站点击继续清理');return}
 }}catch(error){if(active())toast('清理状态刷新失败：'+cloudErrorMessage(error))}finally{deletionPolls.delete(key)}
}
async function permanentDeleteFromTrash(videoId){
 if(Store.localOnly)return;
 const generation=trashViewGeneration,row=CloudState.trash.find(item=>String(item.videoId||item.video?.id)===String(videoId)),title=row?.video?.titleZh||row?.video?.title||`视频 #${videoId}`;
 let accepted;
 if(row?.deletion?.confirmedAt){accepted=await Cloud.retryVideoDeletion(row.deletion.deletionId)}else{
  await flushCloudDraftSync();
  const plan=await Cloud.planPermanentVideoDeletion(videoId,CloudState.revision);
  if(generation!==trashViewGeneration||routePath()!=='/trash')return null;
  if(!confirm(`确定永久删除「${title}」吗？\n\n将清理该视频独占的原片、视频成品、字幕大内容和解析任务。此操作完成后无法恢复；其他视频和学员学习统计不会删除。${Number(plan.sharedObjectCount)?`\n检测到 ${Number(plan.sharedObjectCount)} 个共享源文件，将安全保留。`:''}`))return null;
  accepted=await Cloud.confirmPermanentVideoDeletion(plan.planId,plan.expectedRevision);
 }
 if(row)row.deletion={...row.deletion,...accepted,confirmedAt:accepted.confirmedAt||row.deletion?.confirmedAt||new Date().toISOString()};
 if(generation===trashViewGeneration&&routePath()==='/trash'){renderTrash();toast('已开始后台清理，可以关闭当前页面')}
 return accepted;
}
function importCloudMutation(result){if(result?.error)throw result.error;if(!result?.data?.snapshot)throw new Error('CLOUD_CONTENT_RESPONSE_INVALID');cloudImporting=true;try{Store.importSnapshot(result.data.snapshot,{type:'cloud.import',revision:result.data.revision})}finally{cloudImporting=false}CloudState.revision=Number(result.data.revision)||CloudState.revision}
function timelineInside(words,start,end){return words.length>0&&words.every(word=>Number.isFinite(word.start)&&Number.isFinite(word.end)&&word.end>word.start&&word.start>=start-.05&&word.end<=end+.05)}
function sameTimeline(a=[],b=[]){return a.length===b.length&&a.every((word,index)=>String(word.text||word.word).trim()===String(b[index]?.text||b[index]?.word).trim()&&Math.abs(Number(word.start)-Number(b[index]?.start))<.005&&Math.abs(Number(word.end)-Number(b[index]?.end))<.005)}
function sentenceFromCard(card,existing,{approve=false,fill=false}={}){const input=field=>card.querySelector(`[data-field="${field}"]`),start=Number(input('startTime')?.value),end=Number(input('endTime')?.value),english=String(input('english')?.value||'').trim(),raw=String(input('wordTimings')?.value||'').trim(),number=(existing.order??0)+1;if(!Number.isFinite(start)||!Number.isFinite(end)||start<0||end<=start)throw new Error(`句子 #${number} 的起止时间无效`);if(!english)throw new Error(`句子 #${number} 缺少英文字幕`);let parsed;try{parsed=parseWordTimeline(raw)}catch(error){throw new Error(`句子 #${number}：${error.message}`)}let wordTimings=sameTimeline(parsed,existing.wordTimings||[])?existing.wordTimings:parsed,timingSource=existing.timingSource||'unknown',alignmentBasis=existing.alignmentBasis||{};if(parsed.length&&!sameTimeline(parsed,existing.wordTimings||[]))timingSource='manual';const estimatedBasisChanged=timingSource==='estimated'&&(String(alignmentBasis.english||'')!==english||Math.abs(Number(alignmentBasis.startTime)-start)>.005||Math.abs(Number(alignmentBasis.endTime)-end)>.005);if(!timelineInside(wordTimings,start,end)||estimatedBasisChanged){if(!fill&&wordTimings.length&&!estimatedBasisChanged)throw new Error(`句子 #${number} 的词级时间超出整句范围`);wordTimings=[];timingSource='estimated';alignmentBasis={english,startTime:start,endTime:end}}return {...existing,startTime:start,endTime:end,english,chinese:String(input('chinese')?.value||'').trim(),keyWords:String(input('keyWords')?.value||'').split(',').map(x=>x.trim()).filter(Boolean),grammar:String(input('grammar')?.value||'').trim(),wordTimings,timingSource,alignmentBasis,reviewStatus:approve?'APPROVED':existing.reviewStatus||'REVIEW'}}
function readSentenceDraft(card,existing,options={}){const approve=Boolean(options.approve),resolveTeachingReview=Boolean(options.resolveTeachingReview)||Boolean(card.querySelector('[data-field="resolveTeachingReview"]')?.checked),draft=sentenceFromCard(card,existing,{...options,approve:false}),raw=String(card.querySelector('[data-field="expressions"]')?.value||'[]');let expressions;try{expressions=JSON.parse(raw);if(!Array.isArray(expressions))throw new Error('必须是数组')}catch(error){throw new Error(`句子 #${(existing.order??0)+1} 的重点表达 JSON 无效：${error.message}`)}const selectionChanged=LearningContract.normalizeSurface((draft.keyWords||[]).join(' | '))!==LearningContract.normalizeSurface((existing.keyWords||[]).join(' | ')),sourceChanged=String(draft.english)!==String(existing.english)||selectionChanged,textRevision=Math.max(1,Number(existing.textRevision)||1)+(sourceChanged?1:0);draft.textRevision=textRevision;draft.learningContractVersion=LearningContract.VERSION;draft.selectionLocked=Boolean(card.querySelector('[data-field="selectionLocked"]')?.checked||selectionChanged);draft.selectionSource=draft.selectionLocked?'manual':existing.selectionSource||'ai';draft.selectionRevision=Math.max(0,Number(existing.selectionRevision)||0)+(selectionChanged?1:0);draft.expressions=expressions.map(row=>({...row,surface:String(row?.surface||'').trim(),coreMeaningZh:String(row?.coreMeaningZh||'').trim(),contextMeaningZh:String(row?.contextMeaningZh||'').trim(),usageNoteZh:String(row?.usageNoteZh||'').trim(),source:row?.source==='ai'?'ai':'manual',sourceTextRevision:textRevision,approved:approve,reviewStatus:approve?'APPROVED':'REVIEW'})).filter(row=>row.surface);if(approve&&resolveTeachingReview){const hadPendingTeachingReview=Boolean(existing.segmentationNeedsReview)||(existing.expressions||[]).some(row=>row?.needsReview);draft.segmentationNeedsReview=false;draft.expressions=draft.expressions.map(row=>({...row,needsReview:false}));if(hadPendingTeachingReview)draft.reviewRevision=(Number(existing.reviewRevision)||0)+1}if(approve)draft.reviewStatus='APPROVED';const issues=LearningContract.sentenceIssues(draft,{forPublish:approve});if(approve&&issues.length){const error=new Error(`句子 #${(existing.order??0)+1}：${issues[0].message}`);error.issues=issues;throw error}const changed=['english','chinese','grammar','keyWords','expressions','selectionLocked'].some(key=>JSON.stringify(draft[key])!==JSON.stringify(existing[key]));draft.reviewStatus=approve?'APPROVED':changed?'REVIEW':existing.reviewStatus||'REVIEW';return draft}
function collectSentenceDrafts(videoId,options={}){const current=new Map(Store.listSentences(videoId).map(row=>[String(row.id),row]));return $$('.sentence-row').map(card=>{const existing=current.get(String(card.dataset.sentenceId));if(!existing)throw new Error('发现已失效的字幕行，请刷新后重试');return readSentenceDraft(card,existing,options)})}
