function renderSearchResults(q){const videos=Store.listVideos().filter(v=>!q||(v.title+' '+v.creator+' '+v.status).toLowerCase().includes(q.toLowerCase())).slice(0,10);$('#searchResults').innerHTML=videos.map(v=>`<a class="search-result" href="#/videos/${Number(v.id)}" data-close="searchModal">${videoCoverImage(v)}<span><b>${escapeHtml(v.title)}</b><small>${escapeHtml(v.creator)} · ${escapeHtml(v.status)}</small></span><em>Video</em></a>`).join('')||'<div class="empty">没有结果</div>'}
