function cancelCloudDraftSync(){if(cloudSyncTimer){clearTimeout(cloudSyncTimer);cloudSyncTimer=null}}
function syncCloudDraftNow(){if(Store.localOnly||cloudImporting||!AdminAuth.context||!Cloud)return cloudSyncPromise;cancelCloudDraftSync();cloudSyncPromise=cloudSyncPromise.catch(()=>null).then(async()=>{const result=await Cloud.saveDraft(Store.snapshot(),CloudState.revision);if(result?.error)throw result.error;CloudState.revision=Number(result.data?.revision)||CloudState.revision;return result});return cloudSyncPromise}
function flushCloudDraftSync(){if(cloudSyncTimer)return syncCloudDraftNow();return cloudSyncPromise.catch(()=>syncCloudDraftNow())}
async function persistCreatorStatus(id,status,replacementId=null){
 if(Store.localOnly)return status==='ACTIVE'?Store.restoreCreator(id):Store.deleteCreator(id,replacementId);
 try{await flushCloudDraftSync();importCloudMutation(await Cloud.setCreatorStatus(id,status,replacementId,CloudState.revision))}
 catch(error){if(String(error?.message||'').includes('CONTENT_REVISION_CONFLICT'))await loadAdminCloud();throw error}
 await refreshCloudTrash().catch(()=>toast('操作已保存，回收站列表刷新失败，请刷新页面重试'));
}
async function persistCatalogEntity(kind,input){
 const save=kind==='creator'?Store.saveCreator:Store.saveCollection,prepare=kind==='creator'?Store.prepareCreator:Store.prepareCollection;
 if(Store.localOnly)return save(input);
 try{
  await flushCloudDraftSync();const entity=prepare(input),result=await Cloud.publishEntity(kind,entity,CloudState.revision);
  if(result?.error)throw result.error;
  if(result?.data?.revision==null||!Number.isSafeInteger(Number(result.data.revision))||Number(result.data.revision)<=CloudState.revision)throw new Error('CLOUD_CONTENT_RESPONSE_INVALID');
  CloudState.revision=Number(result.data.revision);
  cloudImporting=true;try{return save(entity)}finally{cloudImporting=false}
 }catch(error){if(String(error?.message||'').includes('CONTENT_REVISION_CONFLICT'))await loadAdminCloud();throw error}
}
function scheduleCloudDraftSync(event){if(Store.localOnly||cloudImporting||event?.detail?.type==='cloud.import'||!AdminAuth.context||!Cloud)return;cancelCloudDraftSync();cloudSyncTimer=setTimeout(()=>{cloudSyncTimer=null;syncCloudDraftNow().catch(error=>toast('云端草稿同步失败：'+(error.message||'请稍后重试')))},700)}
function reserveLocalProcessing(input){
 syncCloudDraftNow();
 cloudSyncPromise=cloudSyncPromise.then(()=>window.EastudyLocalReservation.reserve(input,{
  cloud:Cloud,snapshot:()=>Store.snapshot(),revision:()=>CloudState.revision,
  importMutation:importCloudMutation,saveLater:scheduleCloudDraftSync
 }));
 return cloudSyncPromise;
}
async function queueVideoReplacement(data,existing,creator,file,duration){
 const video={...existing,...data,duration,creator:creator?.name||existing?.creator||'',
  tags:automaticTags({...existing,...data}),collectionIds:existing?.collectionIds||[],status:'DRAFT',pipelineStatus:'QUEUED',
  mediaUrl:'',playback:null,
  processingOptions:{transcript:true,translate:true,dictionary:true,learningAnalysis:true}};
 ['doTranscript','doTranslate','doDictionary','doLearningAnalysis'].forEach(key=>delete video[key]);
 if(!existing)delete video.id;
 await window.EastudyLocalProcessing.submit({file,video,onProgress:setUploadProgress});
 closeModal('videoModal');
 toast('已加入均衡540P处理队列，完成审核后再发布');location.hash='#/pipeline';
}
